// Alegra no documenta la forma exacta de lo que manda el webhook, así que aquí
// no confiamos en ella: buscamos el id donde pueda venir y con ese id volvemos
// a preguntarle a Alegra la factura completa.

const crudo = (items[0] && items[0].json) || {};
const cuerpo = crudo.body !== undefined ? crudo.body : crudo;
const base = Array.isArray(cuerpo) ? cuerpo[0] || {} : cuerpo;

const posibles = [
  base.id,
  base.billId,
  base.idBill,
  base.data && base.data.id,
  base.bill && base.bill.id,
  base.resource && base.resource.id,
  base.payload && base.payload.id,
];

const facturaId = posibles
  .map((v) => (v === undefined || v === null ? '' : String(v).trim()))
  .find((v) => v !== '');

if (!facturaId) {
  throw new Error(
    'No encontré el id de la factura en lo que mandó Alegra. Esto fue lo que llegó: ' +
      JSON.stringify(cuerpo).slice(0, 500)
  );
}

return [{ json: { facturaId } }];

// De la factura que acaban de registrar sacamos lo que sirve para buscar
// duplicados: el proveedor, el número y el monto.

const f = (items[0] && items[0].json) || {};

const nombreDe = (p) => {
  const n = p && p.name;
  if (Array.isArray(n)) return n.filter(Boolean).join(' ');
  if (n && typeof n === 'object') return [n.firstName, n.lastName].filter(Boolean).join(' ');
  return n || 'Proveedor sin nombre';
};

const proveedor = f.provider || f.client || {};
const proveedorId = proveedor.id === undefined || proveedor.id === null ? '' : String(proveedor.id);

if (!proveedorId) {
  throw new Error(
    'La factura ' + (f.id || '?') + ' no trae proveedor, así que no puedo buscar duplicados suyos.'
  );
}

const numeroDe = (x) =>
  String(
    (x.numberTemplate && x.numberTemplate.fullNumber) || x.billNumber || x.number || ''
  );

return [
  {
    json: {
      facturaId: String(f.id),
      numero: numeroDe(f),
      proveedorId,
      proveedor: nombreDe(proveedor),
      fecha: f.date ? String(f.date).slice(0, 10) : '',
      vence: f.dueDate ? String(f.dueDate).slice(0, 10) : '',
      total: Number(f.total ?? 0),
      moneda: (f.currency && f.currency.code) || 'COP',
      observaciones: String(f.observations || f.anotation || ''),
    },
  },
];

// Alegra devuelve máximo 30 facturas de proveedor por llamada, así que el nodo
// anterior hace varias llamadas y entrega una página por cada una.
// Aquí las abrimos para quedar con una factura por item.

const facturas = [];

for (const item of items) {
  const cuerpo = item.json;
  if (Array.isArray(cuerpo)) {
    facturas.push(...cuerpo);
  } else if (Array.isArray(cuerpo.data)) {
    facturas.push(...cuerpo.data);
  } else {
    facturas.push(cuerpo);
  }
}

return facturas.map((factura) => ({ json: factura }));

// ─── Puedes cambiar esto ──────────────────────────────────────────────
const DIAS_DE_MARGEN = 5;        // ventana para buscar el mismo monto
const TOLERANCIA_MONTO = 0.01;   // 0.01 = 1% de diferencia todavía cuenta como igual
const MONEDA = 'COP';
// ──────────────────────────────────────────────────────────────────────

const nueva = $('Preparar la búsqueda').first().json;

const plata = (n) =>
  new Intl.NumberFormat('es-CO', {
    style: 'currency',
    currency: MONEDA,
    maximumFractionDigits: 0,
  }).format(n);

const fecha = (d) => {
  if (!d) return null;
  const f = new Date(String(d).slice(0, 10) + 'T00:00:00');
  return isNaN(f.getTime()) ? null : f;
};

// Para comparar números de factura: 'FC 001' y 'fc-001' son el mismo.
const normalizar = (t) => String(t || '').toLowerCase().replace(/[^a-z0-9]/g, '');

const numeroDe = (x) =>
  String((x.numberTemplate && x.numberTemplate.fullNumber) || x.billNumber || x.number || '');

const fechaNueva = fecha(nueva.fecha);
const numeroNuevo = normalizar(nueva.numero);

const sospechas = [];

for (const item of items) {
  const otra = item.json;
  if (!otra || String(otra.id) === String(nueva.facturaId)) continue;
  // Una factura anulada ya no cuenta como duplicado.
  if (String(otra.status || '').toLowerCase() === 'void') continue;

  const numeroOtra = normalizar(numeroDe(otra));
  const totalOtra = Number(otra.total ?? 0);
  const fechaOtra = fecha(otra.date);

  const mismoNumero = numeroNuevo !== '' && numeroOtra === numeroNuevo;

  let mismoMonto = false;
  let diasAparte = null;
  if (!mismoNumero && nueva.total > 0 && fechaNueva && fechaOtra) {
    diasAparte = Math.abs(Math.round((fechaOtra - fechaNueva) / 86400000));
    const diferencia = Math.abs(totalOtra - nueva.total) / nueva.total;
    mismoMonto = diasAparte <= DIAS_DE_MARGEN && diferencia <= TOLERANCIA_MONTO;
  }

  if (!mismoNumero && !mismoMonto) continue;

  sospechas.push({
    id: String(otra.id),
    numero: numeroDe(otra) || '(sin número)',
    fecha: otra.date ? String(otra.date).slice(0, 10) : '(sin fecha)',
    total: totalOtra,
    totalTexto: plata(totalOtra),
    estado: String(otra.status || ''),
    motivo: mismoNumero
      ? 'tiene el mismo número'
      : 'tiene el mismo monto y se registró ' +
        (diasAparte === 0 ? 'el mismo día' : 'con ' + diasAparte + ' día' + (diasAparte === 1 ? '' : 's') + ' de diferencia'),
    grave: mismoNumero,
  });
}

// Primero las coincidencias por número, que son las más claras.
sospechas.sort((a, b) => Number(b.grave) - Number(a.grave));

const hayDuplicado = sospechas.length > 0;

let mensaje = '';
if (hayDuplicado) {
  const grave = sospechas.some((s) => s.grave);
  mensaje =
    '<b>' + (grave ? 'Ojo: esta factura ya estaba' : 'Revisa esta factura antes de pagarla') + '</b>\n\n' +
    'Acabas de registrar <b>' + (nueva.numero || '(sin número)') + '</b> de <b>' + nueva.proveedor + '</b>\n' +
    'por ' + plata(nueva.total) + ', con fecha ' + (nueva.fecha || '(sin fecha)') + '.\n\n' +
    'Se parece a ' + (sospechas.length === 1 ? 'esta:' : 'estas ' + sospechas.length + ':') + '\n' +
    sospechas
      .slice(0, 5)
      .map((s) => '• <b>' + s.numero + '</b> del ' + s.fecha + ' por ' + s.totalTexto + ' — ' + s.motivo)
      .join('\n') +
    (sospechas.length > 5 ? '\n… y ' + (sospechas.length - 5) + ' más.' : '') +
    '\n\nNo se borró nada. Entra a Alegra y decide cuál dejas.';
}

return [
  {
    json: {
      hayDuplicado,
      cantidad: sospechas.length,
      sospechas,
      mensaje,
      facturaId: nueva.facturaId,
      numero: nueva.numero,
      proveedor: nueva.proveedor,
      total: nueva.total,
      fecha: nueva.fecha,
    },
  },
];
